pub mod manager;
pub mod project;

use anyhow::{Context, Result};
use std::{path::PathBuf, sync::Arc, time::Duration};
use tokio::{process::Command, time::timeout};
use uuid::Uuid;
use x11_context::Context as MessageContext;
use x11_core::{mode::AgentMode, orchestration::{HookEvent, Orchestrator}, verification::{VerificationKind, VerificationPlan, VerificationStep}, AgentSnapshot, AgentState, SubagentSpec};
use x11_model::{CompletionRequest, ModelProvider};
use x11_permissions::{Decision, Operation, Policy};
use x11_protocol::{stream::{ApprovalBroker, ApprovalRequest, EventBus}, AgentEvent, SessionId};
use x11_session::Session;
use x11_tools::{ToolContext, ToolKind, ToolRegistry};
use crate::manager::{AgentManager, AgentManagerConfig, SubagentResult};
use crate::project::{discover_skills, load_agents_md};

#[derive(Debug, Clone)]
pub struct AgentConfig { pub workspace:PathBuf,pub model:String,pub max_iterations:u32,pub auto_approve:bool,pub max_context_tokens:usize,pub session_path:Option<PathBuf>,pub verification_commands:Vec<String>,pub verification_timeout_ms:u64,pub hooks_enabled:bool,pub mode:AgentMode }
impl Default for AgentConfig{fn default()->Self{Self{workspace:std::env::current_dir().unwrap_or_else(|_|PathBuf::from(".")),model:"default".into(),max_iterations:20,auto_approve:false,max_context_tokens:12000,session_path:None,verification_commands:vec!["git diff --check".into()],verification_timeout_ms:120_000,hooks_enabled:false,mode:AgentMode::Normal}}}

pub struct AgentRuntime<P:ModelProvider>{pub snapshot:AgentSnapshot,pub config:AgentConfig,pub provider:Arc<P>,pub tools:ToolRegistry,pub policy:Policy,pub context:MessageContext,pub session:Session,pub orchestration:Orchestrator,pub verification:VerificationPlan,pub events:EventBus,pub approvals:ApprovalBroker,interactive_approvals:bool}
impl<P:ModelProvider+'static> AgentRuntime<P>{
 pub fn new(goal:impl Into<String>,config:AgentConfig,provider:P)->Self{Self::new_shared(goal,config,Arc::new(provider))}
 pub fn new_shared(goal:impl Into<String>,config:AgentConfig,provider:Arc<P>)->Self{let goal=goal.into();let mut orchestration=Orchestrator::default();orchestration.install_defaults();if let Ok(skills)=discover_skills(&config.workspace){for skill in skills{orchestration.register_skill(skill);}}let verification=Self::verification_plan(&config);let(approvals,_)=ApprovalBroker::new(32);Self{snapshot:AgentSnapshot::new(goal.clone(),config.max_iterations),session:Session::new(goal),provider,tools:ToolRegistry::builtins(),policy:Policy::default(),context:MessageContext::default(),config,orchestration,verification,events:EventBus::default(),approvals,interactive_approvals:false}}
 pub fn subscribe(&self)->tokio::sync::broadcast::Receiver<AgentEvent>{self.events.subscribe()}
 pub fn enable_interactive_approvals(&mut self)->tokio::sync::mpsc::Receiver<ApprovalRequest>{let(broker,receiver)=ApprovalBroker::new(32);self.approvals=broker;self.interactive_approvals=true;receiver}
 pub fn resolve_approval(&self,call_id:Uuid,approved:bool)->bool{self.approvals.resolve(call_id,approved)}
 pub async fn run_subagents(&mut self,specs:Vec<SubagentSpec>,manager_config:AgentManagerConfig)->Result<Vec<SubagentResult>>{for spec in &specs{self.emit(AgentEvent::SubagentStarted{agent_id:spec.id.clone(),role:format!("{:?}",spec.role),session_id:SessionId(self.snapshot.session_id)});}let manager=AgentManager::new(self.provider.clone(),self.config.workspace.clone(),self.config.clone(),manager_config);let results=manager.run_parallel(specs).await?;for result in &results{let summary=if result.success{result.output.clone()}else{format!("failed after {} iterations: {}",result.iterations,result.output)};self.emit(AgentEvent::SubagentFinished{agent_id:result.id.clone(),success:result.success,summary});}Ok(results)}
 fn verification_plan(config:&AgentConfig)->VerificationPlan{let mut p=VerificationPlan::default();for c in &config.verification_commands{p.push(VerificationStep{kind:Self::kind_for_command(c),description:format!("verify: {c}"),command:Some(c.clone()),required:true});}p}
 fn kind_for_command(c:&str)->VerificationKind{if c.contains("git diff"){VerificationKind::GitDiff}else if c.contains("test")||c.contains("pytest")||c.contains("nextest"){VerificationKind::Test}else if c.contains("build")||c.contains("cargo check"){VerificationKind::Build}else{VerificationKind::Command}}
 async fn git_state(&self)->(Option<String>,Option<String>){let head=Command::new("git").args(["rev-parse","HEAD"]).current_dir(&self.config.workspace).output().await.ok().filter(|o|o.status.success()).map(|o|String::from_utf8_lossy(&o.stdout).trim().to_owned()).filter(|v|!v.is_empty());let diff=Command::new("git").args(["diff","--binary","--no-ext-diff","--"]).current_dir(&self.config.workspace).output().await.ok().filter(|o|o.status.success()).map(|o|{use sha2::{Digest,Sha256};let mut h=Sha256::new();h.update(&o.stdout);format!("sha256:{:x}",h.finalize())});(head,diff)}
 async fn checkpoint(&mut self,note:&str)->Result<()>{let(head,diff)=self.git_state().await;let id=self.session.checkpoint_with_git(note,head,diff);self.emit(AgentEvent::CheckpointCreated{id,note:note.into()});if let Some(path)=&self.config.session_path{self.session.save_to(path).await?;}Ok(())}
 fn emit(&mut self,event:AgentEvent){self.session.append(event.clone());let _=self.events.emit(event);}
 async fn run_hooks(&mut self,event:HookEvent)->Result<()>{if !self.config.hooks_enabled{return Ok(());}let hooks=self.orchestration.hooks(event).cloned().collect::<Vec<_>>();for hook in hooks{let decision=self.policy.decide_for(Operation::Shell,&hook.command);let allowed=matches!(decision,Decision::Allow)||(matches!(decision,Decision::Ask)&&self.config.auto_approve);if !allowed{self.emit(AgentEvent::Error{message:format!("hook '{}' skipped: shell permission {:?}",hook.name,decision)});continue;}let mut cmd=Command::new(if cfg!(windows){"cmd"}else{"sh"});cmd.args(if cfg!(windows){vec!["/C",hook.command.as_str()]}else{vec!["-lc",hook.command.as_str()]}).current_dir(&self.config.workspace);match timeout(Duration::from_millis(self.config.verification_timeout_ms),cmd.output()).await{Ok(Ok(o)) if o.status.success()=>self.emit(AgentEvent::StateChanged{state:format!("hook:{}:ok",hook.name)}),Ok(Ok(o))=>self.emit(AgentEvent::Error{message:format!("hook '{}' failed: exit={} stderr={}",hook.name,o.status.code().unwrap_or(-1),String::from_utf8_lossy(&o.stderr))}),Ok(Err(e))=>self.emit(AgentEvent::Error{message:format!("hook '{}' spawn failed: {e}",hook.name)}),Err(_)=>self.emit(AgentEvent::Error{message:format!("hook '{}' timed out",hook.name)})}}Ok(())}
 async fn verify(&mut self)->Result<bool>{if self.verification.is_empty(){self.emit(AgentEvent::Verification{passed:true,summary:"verification plan is empty".into()});return Ok(true);}let steps=self.verification.required_steps().cloned().collect::<Vec<_>>();let mut passed=true;for step in steps{let Some(command)=step.command.clone()else{continue};let mut cmd=Command::new(if cfg!(windows){"cmd"}else{"sh"});cmd.args(if cfg!(windows){vec!["/C",command.as_str()]}else{vec!["-lc",command.as_str()]}).current_dir(&self.config.workspace);match timeout(Duration::from_millis(self.config.verification_timeout_ms),cmd.output()).await{Ok(Ok(out))=>{let success=out.status.success();passed&=success;let details=format!("{}\nstdout:\n{}\nstderr:\n{}",step.description,String::from_utf8_lossy(&out.stdout),String::from_utf8_lossy(&out.stderr));self.emit(AgentEvent::Verification{passed:success,summary:details.clone()});self.context.push("verification",details)},Ok(Err(e))=>{passed=false;self.emit(AgentEvent::Verification{passed:false,summary:format!("{}: {e}",step.description)})},Err(_)=>{passed=false;self.emit(AgentEvent::Verification{passed:false,summary:format!("{}: timed out",step.description)})}}}Ok(passed)}
 fn skill_prompt(&self)->String{format!("Available X11 Code operating skills:\n{}",self.orchestration.skills().map(|s|format!("### {}\n{}\nTools: {}",s.name,s.instructions,s.tool_hints.join(", "))).collect::<Vec<_>>().join("\n\n"))}
 fn project_prompt(&self)->String{match load_agents_md(&self.config.workspace){Ok(info) if !info.text.is_empty()=>format!("Project instructions discovered from AGENTS.md files:\n{}",info.text),_=>"No AGENTS.md project instructions were discovered.".into()}}
 async fn request_approval(&mut self,call_id:Uuid,tool:String,reason:String)->Result<bool>{self.emit(AgentEvent::ApprovalRequested{call_id,tool:tool.clone(),reason:reason.clone()});let approved=self.approvals.request(ApprovalRequest{call_id,tool:tool.clone(),reason}).await?;self.emit(AgentEvent::ApprovalResolved{call_id,tool,approved});Ok(approved)}
 pub async fn run(&mut self)->Result<String>{self.run_hooks(HookEvent::BeforeRun).await?;self.emit(AgentEvent::SessionStarted{session_id:SessionId(self.snapshot.session_id)});self.snapshot.transition(AgentState::Planning)?;self.context.push("system",self.system_prompt());self.context.push("system",self.project_prompt());self.context.push("system",self.skill_prompt());self.context.push("system",format!("Execution mode: {:?}. Plan mode is strictly read-only; Review mode is strictly non-mutating.",self.config.mode));self.context.push("user",self.snapshot.goal.clone());self.checkpoint("run started").await?;for _ in 0..self.snapshot.max_iterations{self.snapshot.iteration+=1;self.snapshot.transition(AgentState::Executing)?;self.emit(AgentEvent::StateChanged{state:"executing".into()});self.context.compact(self.config.max_context_tokens);let response=self.provider.complete(CompletionRequest{model:self.config.model.clone(),messages:self.context.to_messages(),tools:self.tools.definitions(),temperature:Some(0.1),max_tokens:Some(8192)}).await.context("model completion failed")?;if !response.text.is_empty(){self.context.push("assistant",response.text.clone());self.emit(AgentEvent::AssistantDelta{text:response.text.clone()});}if response.tool_calls.is_empty(){self.snapshot.transition(AgentState::Verifying)?;let ok=self.verify().await?;if ok&&!response.text.is_empty(){self.snapshot.transition(AgentState::Completed)?;self.emit(AgentEvent::SessionFinished{success:true});self.run_hooks(HookEvent::AfterRun).await?;self.checkpoint("run completed").await?;return Ok(response.text)}if response.text.is_empty(){self.snapshot.last_error=Some("empty model response".into());self.emit(AgentEvent::Error{message:"empty model response".into()});self.snapshot.transition(AgentState::Failed)?;self.emit(AgentEvent::SessionFinished{success:false});self.run_hooks(HookEvent::OnError).await?;self.checkpoint("run failed").await?;anyhow::bail!("model returned an empty response")}self.snapshot.last_error=Some("verification failed".into());self.emit(AgentEvent::Error{message:"verification failed".into()});self.snapshot.transition(AgentState::Planning)?;self.context.push("system","Verification failed. Inspect verification output, repair the root cause, and verify again.");self.checkpoint("verification failed").await?;continue;}for call in response.tool_calls{let id=Uuid::parse_str(&call.id).unwrap_or_else(|_|Uuid::new_v4());self.emit(AgentEvent::ToolRequested{call_id:id,tool:call.name.clone(),input:call.arguments.clone()});self.run_hooks(HookEvent::BeforeTool).await?;let tool=self.tools.get(&call.name).ok_or_else(||anyhow::anyhow!("unknown tool: {}",call.name))?;let op=match tool.kind(){ToolKind::ReadOnly=>Operation::Read,ToolKind::FilesystemWrite=>Operation::FilesystemWrite,ToolKind::Shell=>Operation::Shell,ToolKind::GitWrite=>Operation::GitWrite,ToolKind::Network=>Operation::Network};if !self.config.mode.allows_writes()&&matches!(op,Operation::FilesystemWrite|Operation::GitWrite){let reason=format!("mode {:?} forbids writes",self.config.mode);self.emit(AgentEvent::ApprovalRequested{call_id:id,tool:call.name.clone(),reason});self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:false});self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:"write denied by execution mode".into()});continue;}if !self.config.mode.allows_shell()&&matches!(op,Operation::Shell){let reason=format!("mode {:?} forbids shell",self.config.mode);self.emit(AgentEvent::ApprovalRequested{call_id:id,tool:call.name.clone(),reason});self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:false});self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:"shell denied by execution mode".into()});continue;}let subject=match op{Operation::Shell=>call.arguments["command"].as_str().unwrap_or(""),Operation::GitWrite=>call.arguments["args"].as_array().map(|a|a.iter().filter_map(|v|v.as_str()).collect::<Vec<_>>().join(" ")).unwrap_or_default(),Operation::FilesystemWrite|Operation::Read=>call.arguments["path"].as_str().unwrap_or(""),Operation::Network=>call.name.clone()};let decision=self.policy.decide_for(op,&subject);let allowed=match decision{Decision::Allow=>true,Decision::Deny=>false,Decision::Ask=>{if self.config.auto_approve{self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:true});true}else if self.interactive_approvals{self.request_approval(id,call.name.clone(),format!("permission required for {op:?}" )).await?}else{self.emit(AgentEvent::ApprovalRequested{call_id:id,tool:call.name.clone(),reason:"permission requires approval; rerun with --yes or --tui".into()});self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:false});false}}};if !allowed{self.context.push("tool",format!("{} => DENIED",call.name));self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:"tool call denied by permission policy".into()});continue;}match self.tools.execute(&ToolContext{workspace:self.config.workspace.clone()},&call.name,call.arguments.clone()).await{Ok(out)=>{self.context.push("tool",format!("{} => {out}",call.name));self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:true,output:out})},Err(e)=>{let msg=e.to_string();self.context.push("tool",format!("{} => ERROR: {msg}",call.name));self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:msg.clone()});self.emit(AgentEvent::Error{message:msg})}}self.run_hooks(HookEvent::AfterTool).await?;}self.snapshot.transition(AgentState::Verifying)?;self.emit(AgentEvent::Verification{passed:true,summary:format!("iteration {} completed; tool results returned to context",self.snapshot.iteration)});self.snapshot.transition(AgentState::Planning)?;self.checkpoint(&format!("iteration {} completed",self.snapshot.iteration)).await?;}self.snapshot.last_error=Some("iteration limit reached".into());self.snapshot.transition(AgentState::Failed)?;self.emit(AgentEvent::Error{message:"iteration limit reached".into()});self.emit(AgentEvent::SessionFinished{success:false});self.run_hooks(HookEvent::OnError).await?;self.checkpoint("iteration limit reached").await?;anyhow::bail!("agent iteration limit reached")}
 fn system_prompt(&self)->String{format!("You are X11 Code, an autonomous coding agent. Work only inside the workspace. Goal: {}\nUse tools deliberately. Inspect before editing, make narrow changes, inspect diffs after edits, and use tests or other verification commands when required. Treat every tool result as authoritative and never invent output. Workspace: {}",self.snapshot.goal,self.config.workspace.display())}
}
pub struct Agent;
impl Agent{pub fn new(goal:impl Into<String>)->Self{let _=goal;Self}}
